\label{wang922l1}
Let $K\in\mathbb{R}^{n\times m}$ be of full row rank and set $r\triangleq m-n$. Define
\begin{equation}\label{wang922e2}
K^\dagger= K^\top(KK^\top)^{-1},
\qquad
\Pi_K= I_m-K^\dagger K.
\end{equation}
Then $K^\dagger K$ is the orthogonal projection of $\mathbb{R}^m$ onto $\operatorname{Ran}(K^\top)$, while $\Pi_K$ is the orthogonal projection onto $\operatorname{Ker} K$.
Moreover, there exists a matrix $U_K\in\mathbb{R}^{m\times r}$ such that
\begin{equation}\label{wang922e3}
KU_K=0,
\qquad
U_K^\top U_K=I_r,
\qquad
U_KU_K^\top=\Pi_K.
\end{equation}

\label{Wang921l1}
Suppose that the MF-SDE system \eqref{fmf} is terminally controllable on $[0,T]$.
Then there exists a constant ${\cal C}>0$ such that, for every $x_T\in L^2_{\mathcal F_T}(\Omega;\mathbb R^n)$ satisfying
$\|x_T\|_{L^2_{\mathcal F_T}(\Omega;\mathbb R^n)}\leq 1$,
there is a pair
$(x_0,u(\cdot))\in \mathbb R^n\times L^2_{\mathbb F}(0,T;\mathbb R^m)$
such that $x(T;x_0,u(\cdot))=x_T$, and
\begin{align}\label{Wang921e1}
\|x_0\|^2+\mathbb{E}\int_0^T\|u(t)\|^2\,\mathrm d t \leq {\cal C}.
\end{align}
Moreover, the corresponding state satisfies
\begin{align}\label{Wang921e2}
\mathbb{E}\Big[\sup_{t\in[0,T]}\big\|x\big(t;x_0,u(\cdot)\big)\big\|^2\Big]\leq {\cal C}.
\end{align}

\label{rank-condition}
For any $T>0$, the MF-SDE system \eqref{fmf} is terminally controllable on $[0,T]$ if and only if
\begin{equation}\label{rank-conditions}
\operatorname{Rank}(D)=\operatorname{Rank}(D+\bar D)=n.
\end{equation}
Consequently, \eqref{fmf} is terminally controllable if and only if \eqref{rank-conditions} holds.

\label{wang922p1}
Suppose that $\operatorname{Rank}(D)=\operatorname{Rank}(D+\bar D)=n$. Then the exact controllability of the MF-SDE system \eqref{fmf} is equivalent to that of the MF-BSDE system \eqref{fmf-2}.
Furthermore, suppose that \eqref{fmf} is exactly controllable on $[0,T]$. Then, for every $x_0\in\mathbb{R}^n$ and $x_T\in L^2_{\mathcal{F}_T}(\Omega;\mathbb{R}^n)$, Problems {\rm\bf (NP)$_{x_0,x_T}^T$} and {\rm\bf (COP)$_{x_0,x_T}^T$} admit unique optimal controls $u^*(\cdot)$ and $v^*(\cdot)$, respectively, and
\begin{equation}\label{wang922e8}
u^*(\cdot)= f\big(x^*(\cdot),z^*(\cdot),v^*(\cdot)\big),
\end{equation}
where $\big(x^*(\cdot),z^*(\cdot)\big)$ is the solution to the MF-BSDE \eqref{fmf-2} with terminal condition $x^*(T)=x_T$ and control $v^*(\cdot)$.

\label{wang923l1}
For any $\lambda, x_0\in\mathbb{R}^n$ and $x_T\in L^2_{\mathcal{F}_T}(\Omega;\mathbb{R}^n)$, Problem {\bf (OP)$_{x_0,x_T,\lambda}^T$} admits a unique optimal triple $\big(x^*_\lambda(\cdot),z^*_\lambda(\cdot),v^*_\lambda(\cdot)\big)$. Moreover, there exists a co-state process $y^*_\lambda(\cdot)$ such that
$\big(x^*_\lambda(\cdot),y^*_\lambda(\cdot),z^*_\lambda(\cdot),v^*_\lambda(\cdot)\big)$ satisfies
\begin{equation}\label{fbsde}
\left\{
\begin{aligned}
&\mathrm{d}x^*_\lambda(t)\!=\!\big[{\bf A} \widetilde x^*_\lambda\!+\!\widehat {\bf A} \bar x^*_\lambda
\!+\!{\bf K} \widetilde z^*_\lambda\!+\!\widehat {\bf K}\bar z^*_\lambda\!+\! {\bf L} \widetilde v^*_\lambda\!+\!\widehat {\bf L}\bar v^*_\lambda\big]\,\mathrm d t\!+\!z^*_\lambda\,\mathrm d W(t),\quad t\in [0,T],\\
&\mathrm{d}y^*_\lambda(t)\!=\!\big[\!-\!{\bf A}^{\!\top} \widetilde y^*_\lambda\!-\!\widehat{\bf A}^{\!\top}\bar y^*_\lambda\!+\!Q\widetilde x^*_\lambda\!+\!\widehat Q\bar x^*_\lambda\!+\!S^\top \widetilde z^*_\lambda\!+\!\widehat S^\top \bar z^*_\lambda\big]\,\mathrm d t\\
&\qquad\qquad +\big[\!-\!{\bf K}^{\!\top} \widetilde y^*_\lambda\!-\!\widehat{\bf K}^{\!\top}\bar y^*_\lambda\!+\!S\widetilde x^*_\lambda\!+\!\widehat S\bar x^*_\lambda\!+\!R \widetilde z^*_\lambda\!+\!\widehat R\bar z^*_\lambda\big]\,\mathrm d W(t), \quad t\in [0,T],\\
&x^*_\lambda(T)\!=\!x_T,\quad y^*_\lambda(0)\!=\!\lambda,
\end{aligned}
\right.
\end{equation}
together with the optimality condition
\begin{equation}\label{optimality}
\widetilde v^*_\lambda={\bf L}^\top \widetilde y^*_\lambda,\quad \bar v^*_\lambda=\widehat{\bf L}^\top \bar y^*_\lambda \quad \hbox{\rm a.e.}
\end{equation}
Furthermore, if $x^*_\lambda(0)=x_0$ for some $\lambda\in\mathbb{R}^n$, then $v^*_\lambda(\cdot)$ is the unique optimal control of Problem {\bf (COP)$_{x_0,x_T}^T$}.

\label{wang923r1}
Lemmas \ref{wang923l1}--\ref{wang923l2}, together with Proposition \ref{wang922p1}, reduce the construction of the minimal norm control of Problem {\bf (NP)$_{x_0,x_T}^T$} to the determination of a parameter $\lambda\in\mathbb{R}^n$ satisfying \eqref{wang925e8}. More precisely, the construction proceeds as follows:
\begin{enumerate}
\item [\rm(1)] Solve the Riccati equations \eqref{Riccati-Sigma} and \eqref{Riccati-P}, together with the MF-BSDE \eqref{bsde-varphi}, to obtain $\Sigma$, $P$, $\varphi$, and $\beta$.

\item [\rm(2)] Determine a parameter $\lambda\in\mathbb{R}^n$ such that $x^*_\lambda(0)=x_0$.

\item [\rm(3)] For this choice of $\lambda$, solve the MF-SDE \eqref{sde-y} to obtain $y^*_\lambda(\cdot)$, and then compute the optimal triple $\big(x^*_\lambda(\cdot),z^*_\lambda(\cdot),v^*_\lambda(\cdot)\big)$ from \eqref{feedback-x}, \eqref{feedback-z}, and \eqref{optimality}.

\item [\rm(4)] Recover the minimal norm control $u^*(\cdot)$ from \eqref{wang922e8}.
\end{enumerate}
This procedure provides the basis for the numerical computation of the minimal norm control. It remains to determine a suitable $\lambda$ satisfying the condition in item {\rm (2)}, which will be addressed in the next subsection.

\label{wang924l1}
Suppose that \eqref{fmf} is exactly controllable on $[0,T]$. Then the auxiliary system \eqref{fmf-3} is also exactly controllable on $[0,T]$. Furthermore, the exact controllability of \eqref{fmf-3} on $[0,T]$ is equivalent to the invertibility of the following Gramian:
\begin{align}\label{wang924e3}
G_{\tt aux}\triangleq\mathbb{E}\int_0^T\big[
\widetilde\Phi{\cal L}{\cal L}^\top\widetilde\Phi^\top
+\bar\Phi\widehat{{\cal L}}\widehat{{\cal L}}^\top\bar\Phi^\top
\big]\,\mathrm d t,
\end{align}
where $\Phi(\cdot)$ is the fundamental matrix associated with \eqref{fmf-3}, satisfying
\begin{equation}\label{sde-Phi}
\left\{
\begin{aligned}
&\mathrm{d}\Phi(t)=
-\big[\widetilde\Phi{\cal A}+\bar \Phi\widehat{{\cal A}}\big]\,\mathrm d t
-\big[\widetilde\Phi{\cal K}+\bar \Phi\widehat{{\cal K}}\big]\,\mathrm d W(t),\quad t\in [0,T],\\
&\Phi(0)=I_n.
\end{aligned}
\right.
\end{equation}

Since \eqref{fmf} is exactly controllable on $[0,T]$, it is also terminally controllable on $[0,T]$. Hence, Theorem \ref{rank-condition} and Proposition \ref{wang922p1} imply that \eqref{fmf-2} is exactly controllable on $[0,T]$.

Fix any $x_0\in\mathbb{R}^n$ and $x_T\in L^2_{\mathcal{F}_T}(\Omega;\mathbb{R}^n)$. 
Then there exists a control $v(\cdot)\in L^2_\mathbb{F}(0,T;\mathbb{R}^r)$ such that the corresponding solution $\big(x(\cdot),z(\cdot)\big)$ of \eqref{fmf-2}, with the terminal condition $x(T)=x_T$, satisfies $x(0)=x_0$.
Define
\begin{align*}
{\bf v}=
\begin{pmatrix}
v\\
\Theta^{1/2}\begin{pmatrix}\widetilde x\\\widetilde z\end{pmatrix}
+\widehat\Theta^{1/2}\begin{pmatrix}\bar x\\\bar z\end{pmatrix}
\end{pmatrix}.
\end{align*}
Then ${\bf v}(\cdot)\in L^2_\mathbb{F}(0,T;\mathbb{R}^{m+n})$ and
\begin{align*}
\widetilde{\bf v}=
\begin{pmatrix}
\widetilde v\\
\Theta^{1/2}\begin{pmatrix}\widetilde x\\ \widetilde z\end{pmatrix}
\end{pmatrix},
\qquad
\bar{\bf v}=
\begin{pmatrix}
\bar v\\
\widehat\Theta^{1/2}\begin{pmatrix}\bar x\\ \bar z\end{pmatrix}
\end{pmatrix}.
\end{align*}
Using \eqref{auxi-matrix}, together with ${\cal K}(I_n+\Sigma R)={\bf K}+\Sigma S^\top$ and $\widehat{\cal K}(I_n+\Sigma\widehat R)=\widehat{\bf K}+P\widehat S^\top$, a direct calculation gives
\begin{align*}
{\cal A}\widetilde x+\widehat{\cal A}\bar x+{\cal K}\widetilde z+\widehat{\cal K}\bar z
+{\cal L}\widetilde{\bf v}+\widehat{\cal L}\bar{\bf v}
=
{\bf A}\widetilde x+\widehat{\bf A}\bar x+{\bf K}\widetilde z+\widehat{\bf K}\bar z
+{\bf L}\widetilde v+\widehat{\bf L}\bar v.
\end{align*}
Thus $\big(x(\cdot),z(\cdot)\big)$ also satisfies \eqref{fmf-3} with the terminal condition $x(T)=x_T$ and the control ${\bf v}(\cdot)$. By the uniqueness of the solution to the corresponding MF-BSDE, we have
\[
\big({\bf x}(\cdot),{\bf z}(\cdot)\big)=\big(x(\cdot),z(\cdot)\big),
\]
and consequently ${\bf x}(0)=x(0)=x_0$.
Since $x_0$ and $x_T$ are arbitrary, \eqref{fmf-3} is exactly controllable on $[0,T]$.

Finally, the equivalence between the exact controllability of \eqref{fmf-3} and the invertibility of the Gramian \eqref{wang924e3} follows from \cite[Theorem 4.1]{Yu21}.
This completes the proof.

\label{inver-P}
Let $P(\cdot)$ be the solution to the Riccati equation \eqref{Riccati-P} and $G_{\tt aux}$ be the controllability Gramian \eqref{wang924e3} of the auxiliary system \eqref{fmf-3}. Then
\begin{equation}\label{P=G}
P(0)=G_{\tt aux}.
\end{equation}
Consequently, if \eqref{fmf} is exactly controllable on $[0,T]$, then $P(0)$ is invertible.

We divide the proof into three steps.

\noindent{\bf Step 1.}
Taking expectations in \eqref{sde-Phi}, we have
\begin{equation*}
\left\{
\begin{aligned}
&\dot{\bar\Phi}=-\bar \Phi\widehat{{\cal A}},\qquad \mbox{on } [0,T],\\
&\bar\Phi(0)=I_n.
\end{aligned}
\right.
\end{equation*}
Applying the fundamental theorem of calculus to $\bar\Phi(\cdot)(P(\cdot)-\Sigma(\cdot))\bar\Phi(\cdot)^\top$ and using
$P(T)=\Sigma(T)=0$, $\bar \Phi(0)=I_n$, we obtain

\begin{equation}\label{wang924e4}
\begin{aligned}
P(0)-\Sigma(0)=\int_0^T \big[\bar\Phi\widehat{\mathcal A}(P-\Sigma )\bar\Phi^\top
+\bar\Phi(P-\Sigma )\widehat{\mathcal A}^\top\bar\Phi^\top
-\bar\Phi(\dot P-\dot \Sigma )\bar\Phi^\top\big] \,\mathrm d t.




\end{aligned}
\end{equation}


On the other hand, applying It\^o's formula to $\Phi(\cdot)\Sigma(\cdot)\Phi^\top(\cdot)$ gives
\begin{align*}
\mathrm{d}(\Phi \Sigma \Phi^\top)
&=-\Big[\big(\widetilde\Phi\mathcal A+\bar\Phi\widehat{\mathcal A}\big)\Sigma \Phi^\top +\Phi \Sigma \big(\widetilde\Phi\mathcal A+\bar\Phi\widehat{\mathcal A}\big)^\top
-\Phi\dot \Sigma \Phi^\top \\
&\qquad\quad-\big(\widetilde\Phi\mathcal{K}+\bar\Phi\widehat{\mathcal K}\big)
\Sigma \big(\widetilde\Phi\mathcal{K}+\bar\Phi\widehat{\mathcal K}\big)^\top\Big] \,\mathrm d t
+\cdots\,\mathrm d W(t).
\end{align*}
Since $\Sigma(T)=0$ and $\Phi(0)=I_n$, taking expectations gives
\begin{equation}\label{wang924e5}
\begin{aligned}
\Sigma(0)&=\mathbb{E}\int_0^T\Big\{\widetilde\Phi\big[ {\cal A}\Sigma+\Sigma{\cal A}^\top-{\cal K}\Sigma{\cal K}^\top-\dot\Sigma\big]\widetilde\Phi^\top\\
&\qquad\quad+\bar\Phi\big[ \widehat{\cal A}\Sigma+\Sigma\widehat{\cal A}^\top-\widehat{\cal K}\Sigma\widehat{\cal K}^\top-\dot\Sigma\big]\bar\Phi^\top\Big\}\,\mathrm d t.
\end{aligned}
\end{equation}
Here we use the fact that $\Phi=\widetilde\Phi+\bar\Phi$, $\mathbb{E}[\widetilde\Phi]=0$, and $\mathbb{E}\big[\widetilde \Phi M\bar \Phi^\top\big]=\mathbb{E}\big[\bar \Phi M\widetilde \Phi^\top\big]=0$ for any $M\in\mathbb{R}^{n\times n}$.
Consequently, adding \eqref{wang924e4} and \eqref{wang924e5} yields
\begin{equation}\label{wang924e6}
\begin{aligned}
P(0)&=\mathbb{E}\int_0^T\Big\{\widetilde\Phi\big[ {\cal A}\Sigma+\Sigma{\cal A}^\top-{\cal K}\Sigma{\cal K}^\top-\dot\Sigma\big]\widetilde\Phi^\top\\
&\qquad+\bar\Phi\big[ \widehat{\cal A} P+P \widehat{\cal A}^\top-\widehat{\cal K} \Sigma \widehat{\cal K}^\top-\dot P\big]\bar\Phi^\top\Big\}\,\mathrm d t.
\end{aligned}
\end{equation}

\noindent{\bf Step 2.} We claim that

\begin{equation}\label{wang924e7}
\begin{aligned}
&\dot \Sigma -\mathcal A\Sigma -\Sigma \mathcal A^\top+
\mathcal{K}\Sigma \mathcal{K}^\top=-\mathcal{L}\mathcal{L}^\top,\\
\mbox{and}\quad&
\dot P-
\widehat{\mathcal A}P-
P\widehat{\mathcal A}^\top+
\widehat{\mathcal K}\Sigma \widehat{\mathcal K}^\top
=-\widehat{\mathcal{L}}\widehat{\mathcal{L}}^\top.
\end{aligned}
\end{equation}
We only prove the first identity, since the second one follows in the same vein.
By \eqref{auxi-matrix},
\begin{align*}
&\dot \Sigma -\mathcal A\Sigma -\Sigma \mathcal A^\top+
\mathcal{K}\Sigma \mathcal{K}^\top \notag\\




&\qquad=\dot \Sigma -\mathbf A\Sigma -\Sigma \mathbf A^\top-2\Sigma Q\Sigma 
+\mathcal{K}\Sigma S\Sigma +\Sigma S^\top \Sigma \mathcal{K}^\top
+\mathcal{K}\Sigma \mathcal{K}^\top.

\end{align*}
Since $ {\bf K}+\Sigma S^\top=\mathcal{K}(I+\Sigma R)$, the Riccati equation \eqref{Riccati-Sigma} can be rewritten as 
\[             
\dot \Sigma -\mathbf A\Sigma -\Sigma \mathbf A^\top-\Sigma Q\Sigma +
 {\bf L}{\bf L}^\top
+\mathcal{K}\Sigma \mathcal{K}^\top
+\mathcal{K}\Sigma R\Sigma \mathcal{K}^\top=0.
\]
Hence, comparing the above two equations gives
\begin{align}
&\dot \Sigma -\mathcal A\Sigma -\Sigma \mathcal A^\top+
\mathcal{K}\Sigma \mathcal{K}^\top\notag\\
&\qquad=-\Sigma Q\Sigma - {\bf L}{\bf L}^\top
-\mathcal{K}\Sigma R\Sigma \mathcal{K}^\top
+\mathcal{K}\Sigma S\Sigma +\Sigma S^\top \Sigma \mathcal{K}^\top.\label{wang924e10}
\end{align}


On the other hand, by \eqref{wang923e1}, it holds that
\begin{align*}
(-\Sigma,\mathcal{K}\Sigma )\Theta(-\Sigma,\mathcal{K}\Sigma )^\top
=\Sigma Q\Sigma+\mathcal{K}\Sigma R\Sigma \mathcal{K}^\top -\mathcal{K}\Sigma S\Sigma -\Sigma S^\top \Sigma \mathcal{K}^\top.
\end{align*}
Therefore, by the definition of ${\cal L}$ in \eqref{auxi-matrix},
\begin{align}
\mathcal{L}\mathcal{L}^\top


=\Sigma Q\Sigma +{\bf L}{\bf L}^\top
+\mathcal{K}\Sigma R\Sigma \mathcal{K}^\top-\mathcal{K}\Sigma S\Sigma -\Sigma S^\top \Sigma \mathcal{K}^\top.
\label{wang924e11}
\end{align}
Now the assertion on $\Sigma$ in \eqref{wang924e7} can be established by combining \eqref{wang924e10} and \eqref{wang924e11}.
The $P$-part in \eqref{wang924e7} follows analogously.

\noindent
{\bf Step 3.} A combination of \eqref{wang924e6}, \eqref{wang924e7} and the definition of the Gramian $G_{\tt aux}$ in \eqref{wang924e3} implies that
\begin{align*}
P(0)=\mathbb{E}\int_0^T\big[\widetilde\Phi {\cal L}{\cal L}^\top \widetilde\Phi^\top
+\bar\Phi\widehat{\cal L}\widehat{\cal L}^\top\bar\Phi^\top\big]\,\mathrm d t=G_{\tt aux}.
\end{align*}
That settles the assertion \eqref{P=G}.

Under the exact controllability assumption on the original system \eqref{fmf}, Lemma \ref{wang924l1} implies that the auxiliary system \eqref{fmf-3} is exactly controllable. Hence its Gramian $G_{\tt aux}$ is invertible. Together with \eqref{P=G}, this yields the invertibility of $P(0)$.
This completes the proof.

\label{wang924c1}
Suppose that the MF-SDE system \eqref{fmf} is exactly controllable on $[0,T]$. Let $\Sigma(\cdot), P(\cdot)$, and $\big(\varphi(\cdot),\beta(\cdot)\big)$ be the solutions to the Riccati equations \eqref{Riccati-Sigma}, \eqref{Riccati-P}, and the MF-BSDE \eqref{bsde-varphi}, respectively. Define $\lambda$ by \eqref{wang924e12}, and let $y^*_\lambda(\cdot)$ be the solution of \eqref{sde-y} corresponding to this choice of $\lambda$. Then the optimal triple $\big(x^*_\lambda(\cdot),z^*_\lambda(\cdot),v^*_\lambda(\cdot)\big)$ of Problem {\bf (OP)$_{x_0,x_T,\lambda}^T$} is given by
\begin{equation}\label{OP-triple}
\left\{
\begin{aligned}
&x^*_\lambda=-P\bar y^*_\lambda-\Sigma \widetilde y^*_\lambda+\varphi,\\
&z^*_\lambda=(I+\Sigma R)^{-1}\big[\Sigma  \big({\bf K}^\top+S\Sigma\big) \widetilde y^*_\lambda-\Sigma S\widetilde \varphi+\widetilde\beta\big]\\
&\qquad\quad+(I+\Sigma \widehat R)^{-1}\big[\Sigma  \big(\widehat {\bf K}^\top+\widehat S P\big) \bar y^*_\lambda-\Sigma \widehat S\bar \varphi+\bar\beta\big], \\
&v^*_\lambda={\bf L}^\top \widetilde y^*_\lambda+\widehat{\bf L}^\top \bar y^*_\lambda.
\end{aligned}
\right.
\end{equation}






Moreover, the minimal norm control $u^*(\cdot)$ of Problem {\bf (NP)$_{x_0,x_T}^T$} is given by
\begin{equation}\label{NP-control}
u^*=D^\top(DD^\top)^{-1} \big[\widetilde z^*_\lambda-C\widetilde x^*_\lambda\big]+U \widetilde v^*_\lambda 
+ \widehat D^\top(\widehat D\widehat D^\top)^{-1} \big[\bar z^*_\lambda-\widehat C \bar x^*_\lambda\big]+\widehat U \bar v^*_\lambda,
\end{equation}
where $U$ and $\widehat U$ are the matrices fixed in \eqref{decom}.

\label{wang925c1}
Suppose that the MF-SDE system \eqref{fmf} is exactly controllable on $[0,T]$, and let $\lambda$ be given by \eqref{wang924e12}. Then the unique minimal norm control of the auxiliary system \eqref{fmf-3} satisfying ${\bf x}(0)=x_0$ and ${\bf x}(T)=x_T$ is given by
\begin{equation}\label{wang925e1}
{\bf v}^*
=\big[
{\cal L}^\top \widetilde\Phi^\top
+\widehat{\cal L}^\top\bar\Phi^\top
\big]\lambda.
\end{equation}
More precisely,
\begin{align*}
\|{\bf v}^*(\cdot)\|_{L^2_\mathbb{F}(0,T;\mathbb{R}^{m+n})}
&=\inf\Big\{\|{\bf v}(\cdot)\|_{L^2_\mathbb{F}(0,T;\mathbb{R}^{m+n})}\,\big|\, {\bf v}(\cdot)\in L^2_\mathbb{F}(0,T;\mathbb{R}^{m+n}),\\
&\qquad\qquad\mbox{ and } {\bf x}(0;x_T,{\bf v}(\cdot))=x_0\Big\}.
\end{align*}
Moreover,
\begin{equation}\label{wang925e2}
\|{\bf v}^*(\cdot)\|_{L^2_\mathbb{F}(0,T;\mathbb{R}^{m+n})}^2
=
\big\langle
P(0)^{-1}\big(\varphi(0)-x_0\big),
\varphi(0)-x_0
\big\rangle
=
\langle P(0)\lambda,\lambda\rangle.
\end{equation}
